sql.if:

and t.order_status in

    #{item}


and (t.process_id is null or t.process_id = '' or t.process_id = #{param.userId})

AND (t.enlarge_flag = #{param.enlargeFlag,jdbcType=VARCHAR}

    OR t.enlarge_flag is null

)
AND t.warning_source IN ('1', '4')

and (t.order_status in

    #{item}


    or t.enable_acceptance_mode = #{param.enableAcceptanceMode}


    and t.enable_acceptance_mode != '1'

)

and(
(t.county_code in
#{item.countyId}
and t.warning_source = '9') or
(t.county_code in
#{item.countyId}
and t.warning_source = '10') or
(t.device_code in
#{item}
and t.warning_source in ('1','3','4','8'))
or (t.warning_source = '2' AND FIND_IN_SET(t.find_name, #{param.orgUserListString}))
)

mapper.sql:
WHERE dataTable.longitude IS NOT NULL AND dataTable.latitude IS NOT NULL

    AND (dataTable.alarm_body like concat('%',#{param.alarmBody,jdbcType=VARCHAR},'%') OR dataTable.warning_order_id like concat('%',#{param.alarmBody,jdbcType=VARCHAR},'%'))


    AND DATE_FORMAT(dataTable.alarm_time, '%Y-%m-%d' ) >= DATE_FORMAT(#{param.webStartDate}, '%Y-%m-%d' )
    AND DATE_FORMAT(dataTable.alarm_time, '%Y-%m-%d' ) <= DATE_FORMAT(#{param.webEndDate}, '%Y-%m-%d' )


    AND dataTable.warning_type_id = #{param.warningTypeId,jdbcType=VARCHAR}


    AND dataTable.warning_order_id = #{param.warningOrderId,jdbcType=VARCHAR}


    and dataTable.warning_order_id in

        #{item}



    AND dataTable.emergency_level = #{param.emergencyLevel,jdbcType=VARCHAR}


    and dataTable.enable_acceptance_mode = #{param.enableAcceptanceMode}


    AND dataTable.order_status = #{param.orderStatus,jdbcType=VARCHAR}
    and dataTable.enable_acceptance_mode != '1'


    AND dataTable.longitude = #{param.longitude,jdbcType=VARCHAR}


    AND dataTable.latitude = #{param.latitude,jdbcType=VARCHAR}



    AND dataTable.order_status

        #{status}




    and dataTable.importance_level = #{param.importanceLevel}


    and (dataTable.order_status in

        #{item}


        or dataTable.enable_acceptance_mode = #{param.enableAcceptanceMode}


        and dataTable.enable_acceptance_mode != '1'

    )


    and dataTable.device_code in

        #{item}



    and dataTable.warning_source in

        #{item}

mapper.select:
SELECT

FROM vm_warning_order_collection_t dataTable

and dataTable.delete_flag = '0' and dataTable.collection_creator = #{param.collectionCreator,jdbcType=CHAR}
${param.dataScope}
order by dataTable.alarm_time desc
